    'perc.shaker',    // 14 Shaker
    'fx.laser',       // 15 FX
    // --- the voices a 5 x 5 grid adds ---
    'kick.tight',     // 16 Kick 2
    'snare.high',     // 17 Snare 2
    'hat.open',       // 18 Open Hat
    'tom.floor',      // 19 Tom Fl
    'cym.crash',      // 20 Crash
